UPDATE services SET data='{"slug":"veb-sayt","number":"01","name":"Veb-sayt","short":"Landing, vizitka sayt yoki internet-do‘kon — telefon va kompyuterda birdek qulay.","description":"Biznesingizni internetda tanishtiradigan tez va tushunarli sayt. Matn tuzilishi, dizayn, dasturlash va domenga ulashgacha o‘zimiz bajaramiz.","features":["Sahifalar tuzilmasi va matn rejasi","Shablonsiz, brendingizga mos dizayn","Telefon, planshet va kompyuterga moslashgan ko‘rinish","Murojaat formasi — xabar darhol Telegram’ga keladi","Telefon, Telegram va xarita tugmalari","Tez yuklanish: Google PageSpeed’da yashil ko‘rsatkich","Asosiy SEO: sarlavha va tavsiflar, sitemap, Google Search Console va Yandex Webmaster","Google Analytics va Yandex Metrika","Domen, hosting va SSL (https) ulash","Ishga tushirishdan oldin turli telefon va brauzerlarda tekshiruv"],"icon":"web","price":"1 200 000 so‘mdan","term":"2 haftadan","packages":[{"name":"Landing","price":"1 200 000 so‘mdan","term":"2 haftadan","features":["Bitta sahifa: taklif, afzalliklar, savol-javob va aloqa","Reklamadan keladigan mijozlar uchun moslangan"],"recommended":false,"fit":"Bitta xizmat yoki mahsulotni tanishtirmoqchiman","hidden":false},{"name":"Vizitka sayt","price":"2 400 000 so‘mdan","term":"2 haftadan","features":["5 sahifagacha: bosh sahifa, xizmatlar, biz haqimizda, ishlar, aloqa","Admin panel: matn, rasm va narxlarni o‘zingiz o‘zgartirasiz","Ikki til: o‘zbek va rus"],"recommended":true,"fit":"Kompaniyam haqida bir necha sahifa kerak","hidden":false},{"name":"Internet-do‘kon","price":"","term":"","features":["Mahsulotlar katalogi, filtr va qidiruv","Savat va buyurtma berish","Payme va Click orqali to‘lov","Mahsulot va buyurtmalarni admin paneldan boshqarish","Yangi buyurtma haqida Telegram’ga xabar","Ikki til: o‘zbek va rus"],"recommended":false,"fit":"Internetda sotmoqchiman","hidden":false}],"published":true}',updated_at=CURRENT_TIMESTAMP WHERE id='veb-sayt' AND json_extract(data,'$.features')=json('["Telefon va kompyuterga moslashgan dizayn","Murojaat formasi va Telegram’ga xabar","Domen va hostingga ulash"]') AND json_extract(data,'$.price')='1 200 000 so‘mdan';
UPDATE services SET data='{"slug":"telegram-bot","number":"02","name":"Telegram bot","short":"Buyurtma qabul qiladigan bot yoki Telegram ichida ochiladigan to‘liq ilova (Mini App).","description":"Mijozlaringiz allaqachon Telegram’da. Buyurtma qabul qiladigan, savollarga javob beradigan va sizga xabar yuboradigan bot yasaymiz. Kattaroq vazifa uchun — Telegram ichida ochiladigan to‘liq ilova (Mini App).","features":["Bot ssenariysi: menyu, tugmalar va qadamlar","O‘zbek va rus tillari","Buyurtma, ariza yoki qabulga yozilishni qabul qilish","Yangi buyurtma haqida sizga va xodimlarga xabar","Foydalanuvchilarga ommaviy xabar yuborish","Foydalanuvchilar va buyurtmalar statistikasi","Serverga o‘rnatish va to‘xtovsiz ishlashini kuzatish"],"icon":"telegram","price":"1 200 000 so‘mdan","term":"1 haftadan","packages":[{"name":"Telegram bot","price":"1 200 000 so‘mdan","term":"1 haftadan","features":["Tugmali menyu va katalog","Buyurtmalar admin chatga yoki Google Sheets’ga tushadi"],"recommended":true,"fit":"Oddiy bot: menyu, buyurtma, xabarnoma","hidden":false},{"name":"Mini App","price":"","term":"1,5 haftadan","features":["Telegram ichida ochiladigan ilova oynasi: katalog, savat, profil","Mahsulot va buyurtmalarni boshqarish uchun admin panel","Payme va Click orqali to‘lov"],"recommended":false,"fit":"Telegram ichida to‘liq ilova kerak","hidden":false}],"published":true}',updated_at=CURRENT_TIMESTAMP WHERE id='telegram-bot' AND json_extract(data,'$.features')=json('["Menyu va tugmalar","Buyurtma yoki ariza qabul qilish","Admin uchun xabarnomalar"]') AND json_extract(data,'$.price')='1 200 000 so‘mdan';
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('ai-yordamchi','ai-yordamchi','{"slug":"ai-yordamchi","number":"03","name":"AI yordamchi","short":"Savollarga o‘zi javob beradigan, ariza yig‘adigan va kerak bo‘lsa xodimga uzatadigan AI chatbot.","description":"Mijozlaringiz kechasi ham savol beradi. AI yordamchi sizning narxlaringiz, xizmatlaringiz va qoidalaringiz asosida o‘zbek va rus tilida javob beradi, arizani yozib oladi va murakkab savolni xodimga uzatadi. Telegram’da yoki saytingizda ishlaydi.","features":["Bilimlar bazasi: narxlar, xizmatlar, savol-javoblar va hujjatlaringiz","O‘zbek (lotin va kirill) va rus tillarida javob","Ariza va kontaktlarni yozib olish","Murakkab savolni xodimga uzatish","Yangi ariza haqida Telegram’ga xabar","Javoblarni admin paneldan tahrirlash","Suhbatlar tarixi va statistika","Birinchi oy davomida javoblarni sozlab borish","AI xizmati (token) to‘lovi alohida — oylik sarfni oldindan hisoblab beramiz"],"icon":"ai","price":"4 800 000 so‘mdan","term":"2 haftadan","packages":[{"name":"AI chatbot","price":"4 800 000 so‘mdan","term":"2 haftadan","features":["Bitta kanal: Telegram yoki sayt","Ariza yig‘ish va xodimga uzatish"],"recommended":true,"fit":"Savollarga o‘zi javob beradigan yordamchi kerak","hidden":false},{"name":"AI agent","price":"","term":"","features":["Bir necha kanal: Telegram, sayt, Instagram","Buyurtma qabul qilish va to‘lov havolasi","CRM yoki 1C bilan ulanish","Ovozli xabarlarni tushunish"],"recommended":false,"fit":"Buyurtma, to‘lov va CRM bilan ishlaydigan yordamchi kerak","hidden":false}],"published":true}',1);
UPDATE services SET data='{"slug":"ilova","number":"04","name":"Ilova","short":"Veb-ilova, CRM yoki mobil ilova — ishingizni avtomatlashtiradigan dastur.","description":"Jadval va qog‘ozda yuritilayotgan ishni bitta dasturga jamlaymiz: mijozlar, buyurtmalar, hisobotlar. Kerak bo‘lsa, telefon uchun ilova ham yasaymiz.","features":["Ish jarayonlarini o‘rganish va tizim rejasi","Bosiladigan prototip — boshlashdan oldin ko‘rasiz","Foydalanuvchilar, rollar va ruxsatlar","Mijozlar, buyurtmalar va vazifalar bazasi","Hisobotlar va grafiklar","Telegram orqali xabarnomalar","Excel’dagi ma’lumotlarni ko‘chirish","Har bosqichda ishlaydigan versiyani ko‘rsatish","Muntazam zaxira nusxa va himoyalangan kirish","Serverga o‘rnatish"],"icon":"app","price":"3 600 000 so‘mdan","term":"","packages":[{"name":"Veb-ilova (CRM)","price":"3 600 000 so‘mdan","term":"","features":["Brauzerda ishlaydi — kompyuter va telefonda","Savdo bosqichlari va menejerlar ko‘rsatkichlari"],"recommended":true,"fit":"Brauzerda ishlaydigan tizim kerak","hidden":false},{"name":"Mobil ilova","price":"","term":"","features":["Android va iOS uchun","Push-xabarnomalar","Server va admin panel","Google Play va App Store’ga joylash"],"recommended":false,"fit":"Telefonga o‘rnatiladigan ilova kerak","hidden":false}],"published":true}',updated_at=CURRENT_TIMESTAMP WHERE id='ilova' AND json_extract(data,'$.features')=json('["Foydalanuvchilar va ruxsatlar","Ma’lumotlar bazasi","Hisobotlar"]') AND json_extract(data,'$.price')='3 600 000 so‘mdan';
UPDATE services SET data='{"slug":"dizayn","number":"05","name":"Dizayn","short":"Yangi sayt yoki ilova uchun dizayn va mavjud saytni qayta dizayn qilish.","description":"Foydalanuvchi nimani, qayerda bosishini o‘ylab chiqamiz va buni toza, zamonaviy ko‘rinishga keltiramiz. Natija — dasturchiga tayyor Figma maketlari.","features":["Foydalanuvchilar va raqobatchilarni o‘rganish","Sahifalar sxemasi va foydalanuvchi yo‘li","Shablonsiz vizual dizayn","Bosiladigan prototip","Telefon, planshet va kompyuter ko‘rinishlari","Ranglar, shriftlar va komponentlar tizimi","Dasturchiga tayyor Figma maketlari"],"icon":"design","price":"","term":"","packages":[{"name":"Sayt dizayni","price":"","term":"","features":["Yangi sayt yoki ilova uchun to‘liq dizayn"],"recommended":false,"fit":"Yangi loyiha uchun dizayn kerak","hidden":false},{"name":"Qayta dizayn (UI/UX)","price":"","term":"","features":["Mavjud sayt yoki ilovani tahlil qilish","Foydalanish qulayligini yaxshilash","Yangi, zamonaviy ko‘rinish"],"recommended":false,"fit":"Mavjud saytim eskirgan","hidden":false}],"published":true}',updated_at=CURRENT_TIMESTAMP WHERE id='dizayn' AND json_extract(data,'$.features')=json('["Figma maketlari","Telefon va kompyuter ko‘rinishi","Ranglar va shriftlar tizimi"]') AND json_extract(data,'$.price')='';
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('integratsiyalar','integratsiyalar','{"slug":"integratsiyalar","number":"06","name":"Integratsiyalar","short":"Sayt, bot yoki ilovangizni Payme, Click, CRM, 1C va SMS xizmatlariga ulaymiz.","description":"Mijoz saytda yoki botda to‘laydi, buyurtma CRM’ga tushadi, mijozga SMS boradi, sizga Telegram’da xabar keladi — hech narsani qo‘lda ko‘chirmaysiz. Boshqalar yasagan saytga ham ulaymiz.","features":["To‘lov: Payme, Click, Uzum, Uzcard va Humo kartalari","CRM: amoCRM, Bitrix24","Hisob va ombor: 1C, МойСклад, Billz","SMS: Eskiz, Playmobile","Telegram xabarnomalari va Google Sheets","To‘lov tizimida merchant ochishda yordam","Avval sinov rejimida tekshirish, keyin jonli ulash","To‘lov va buyurtma holati avtomatik yangilanadi"],"icon":"integration","price":"800 000 so‘mdan","term":"1 haftadan","packages":[{"name":"To‘lov tizimlari","price":"1 500 000 so‘mdan","term":"1 haftadan","features":["Payme, Click, Uzum","Uzcard va Humo kartalari","To‘lov holati buyurtmaga avtomatik yoziladi"],"recommended":true,"fit":"Saytimda yoki botimda to‘lov qabul qilmoqchiman","hidden":false},{"name":"CRM","price":"1 500 000 so‘mdan","term":"","features":["amoCRM yoki Bitrix24","Sayt, bot va formalardan arizalar"],"recommended":false,"fit":"Arizalar CRM’ga o‘zi tushsin","hidden":false},{"name":"SMS va xabarnomalar","price":"800 000 so‘mdan","term":"","features":["Eskiz yoki Playmobile","Tasdiqlash kodi va buyurtma holati haqida SMS","Telegram xabarnomalari"],"recommended":false,"fit":"Mijozlarga SMS yubormoqchiman","hidden":false},{"name":"1C va ombor","price":"","term":"","features":["1C, МойСклад yoki Billz","Mahsulot, qoldiq va narxlar almashinuvi"],"recommended":false,"fit":"1C yoki omborim bilan bog‘lash kerak","hidden":false}],"published":true}',1);
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('seo','seo','{"slug":"seo","number":"07","name":"SEO","short":"Saytingiz Google va Yandex’da yuqorida chiqishi uchun audit, sozlash va oylik ish.","description":"Mijozlar sizni qidiruvda topishi uchun saytning texnik holatini tuzatamiz, sahifalarni kerakli so‘zlarga moslaymiz va har oy qilingan ish va natijani hisobot bilan ko‘rsatamiz. Qidiruvdagi o‘rinni hech kim kafolatlay olmaydi, shuning uchun natijani raqamlar bilan kuzatamiz.","features":["O‘zbek va rus tilidagi kalit so‘zlar va raqobatchilar tahlili","Texnik audit: tezlik, indeksatsiya, sitemap, robots.txt, mobil ko‘rinish","Sarlavha, tavsif va matnlarni optimallashtirish","Savol-javob bloklari va tuzilgan ma’lumotlar (schema)","Google Search Console va Yandex Webmaster","Google Biznes profili, Yandex Biznes va 2GIS","Hisobot: nima qilindi va natija qanday"],"icon":"seo","price":"1 500 000 so‘mdan","term":"1 haftadan","packages":[{"name":"SEO-audit va sozlash","price":"1 500 000 so‘mdan","term":"1 haftadan","features":["Bir martalik ish","Topilgan xatolarni tuzatish","Yozma hisobot va keyingi qadamlar"],"recommended":false,"fit":"Saytim nega chiqmayotganini bilmoqchiman","hidden":false},{"name":"Oylik SEO","price":"2 500 000 so‘m/oy","term":"3 oydan","features":["Har oy matn va texnik ishlar","Blog maqolalari","Oylik hisobot va keyingi oy rejasi"],"recommended":true,"fit":"Saytim Google’da yuqorida chiqsin","hidden":false}],"published":true}',1);
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('texnik-yordam','texnik-yordam','{"slug":"texnik-yordam","number":"08","name":"Texnik yordam","short":"Saytingiz yoki botingiz doim ishlashi, xavfsiz va yangilangan bo‘lishi uchun oylik xizmat.","description":"Har bir loyihamizda ishga tushgandan keyin 3 oy bepul texnik yordam bor. Undan keyin, yoki boshqalar yasagan sayt va botlar uchun — oylik xizmat: kuzatamiz, zaxira olamiz, xatoni tuzatamiz va o‘zgarishlarni kiritamiz.","features":["Sayt yoki bot ishlashini kuzatish","Muntazam zaxira nusxa","Xavfsizlik yangilanishlari va himoya","Xatolarni tuzatish","Matn, rasm va narxlarni yangilash","Domen, hosting va SSL muddatini kuzatish","Tezlik tekshiruvi","Boshqalar yasagan sayt va botlarni ham olamiz"],"icon":"support","price":"500 000 so‘m/oydan","term":"","packages":[{"name":"Asosiy","price":"500 000 so‘m/oy","term":"","features":["Kuzatish, zaxira va xavfsizlik","Kichik o‘zgarishlar"],"recommended":false,"fit":"Saytim to‘xtab qolmasin","hidden":false},{"name":"Kengaytirilgan","price":"1 500 000 so‘m/oy","term":"","features":["Kuzatish, zaxira va xavfsizlik","Yangi bo‘lim va sahifalar qo‘shish","Shoshilinch murojaatga tezkor javob","Oylik hisobot"],"recommended":true,"fit":"Saytim doim yangilanib tursin","hidden":false}],"published":true}',1);
